export function createHistorySettings(getAccounts){
 const api=window.zlDesktop,card=document.createElement('details');card.className='settings-card history-settings';card.open=true;
 card.innerHTML=`<summary>聊天记录 <span class="settings-badge">本机加密保存</span></summary><div class="history-form">
 <div class="history-row"><label>保存聊天记录</label><div><label class="history-check"><input id="historyEnabled" type="checkbox">保存（仅保存在本机）</label><p class="settings-caption">每 30 秒采集各运行账号当前打开聊天的最近文字和图片；切换前未采集的内容可用历史同步补充。图片单张最多 10 MB，译文保存已有翻译结果。</p></div></div>
 <div class="history-row"><label>每天自动导出</label><div class="history-inline"><input id="historyAutoExport" type="checkbox"><input id="historyTime" type="time" value="23:30"></div></div>
 <div class="history-row"><label>导出到</label><div><div class="history-inline"><input id="historyDirectory" readonly><button type="button" class="button quiet" data-action="directory">更换…</button><button type="button" class="button quiet" data-action="open">打开文件夹</button></div><p class="settings-caption">本机记录加密保存；导出的 HTML 可离线查看，内容为明文，请妥善保管。</p></div></div>
 <div class="history-row"><label>本机保存</label><select id="historyRetention"><option value="30">30 天</option><option value="90">90 天</option><option value="180">180 天</option><option value="365">1 年</option><option value="forever">永久保留</option></select></div>
 <div class="history-row"><span>已保存</span><strong class="history-saved"></strong></div>
 <div class="history-row"><label>同步历史聊天记录</label><div><div class="history-inline"><select id="historyAccount"></select><select id="historyDays"><option value="7">最近 7 天</option><option value="30" selected>最近 30 天</option><option value="90">最近 90 天</option><option value="all">全部可用历史</option></select><button type="button" class="button quiet" data-action="sync">开始同步</button></div><p class="settings-caption">读取 WhatsApp 可提供的历史；每聊天单次最多读取 10000 条。休眠、离线、图片下载失败会报告，不表示已同步全部历史。</p></div></div>
 <div class="history-row"><label>手动导出</label><div class="history-inline"><select id="historyExportRange"><option value="all">全部（每个聊天一个文件）</option><option value="day">指定日期</option></select><input type="date" id="historyExportDate" hidden><button type="button" class="button quiet" data-action="export">导出</button></div></div>
 <div class="history-row"><span>上次自动导出日期</span><span class="history-last"></span></div>
 </div><p class="settings-feedback history-feedback" role="status"></p>`;
 const q=s=>card.querySelector(s);let prefs=null,refreshing=false,working=false;
 const feedback=(t,error=false)=>{q('.history-feedback').textContent=t;q('.history-feedback').classList.toggle('error',error)};
 function paint(){if(!prefs)return;q('#historyEnabled').checked=prefs.enabled;q('#historyAutoExport').checked=prefs.autoExport;q('#historyAutoExport').disabled=!prefs.enabled;q('#historyTime').value=prefs.time;q('#historyTime').disabled=!prefs.enabled||!prefs.autoExport;q('#historyDirectory').value=prefs.directory;q('#historyRetention').value=prefs.retention;q('.history-saved').textContent=prefs.messages+' 条消息 · '+prefs.images+' 张图片 · '+(prefs.bytes/1048576).toFixed(2)+' MB';q('.history-last').textContent=prefs.lastExport||'尚未执行';q('[data-action=sync]').disabled=!prefs.enabled||prefs.busy||working;q('[data-action=export]').disabled=!prefs.messages||working;if(prefs.lastError&&!working)feedback(prefs.lastError,true)}
 async function save(){if(!prefs)return;try{prefs=await api.historySave({...prefs,enabled:q('#historyEnabled').checked,autoExport:q('#historyAutoExport').checked,time:q('#historyTime').value,directory:q('#historyDirectory').value,retention:q('#historyRetention').value});feedback('已保存并应用');paint()}catch(e){feedback(e.message,true);paint()}}
 for(const id of ['Enabled','AutoExport','Time','Retention'])q('#history'+id).onchange=save;
 async function action(fn){if(working)return;working=true;paint();try{await fn()}catch(e){feedback(e.message,true)}finally{working=false;await refresh()}}
 q('[data-action=directory]').onclick=()=>action(async()=>{const path=await api.historyDirectory();if(path){q('#historyDirectory').value=path;await save()}});
 q('[data-action=open]').onclick=()=>action(()=>api.historyOpen());
 q('[data-action=sync]').onclick=()=>action(async()=>{feedback('正在读取历史记录，请保持账号在线…');const id=q('#historyAccount').value,ids=id==='all-whatsapp'?getAccounts().map(a=>a.id):[id];const r=await api.historySync({ids,days:q('#historyDays').value});feedback('已读取 '+r.count+' 条，重复消息自动合并。'+r.errors.join('；'),!!r.errors.length)});
 q('#historyExportRange').onchange=()=>q('#historyExportDate').hidden=q('#historyExportRange').value!=='day';
 q('[data-action=export]').onclick=()=>action(async()=>{const date=q('#historyExportRange').value==='day'?q('#historyExportDate').value:null;if(date==='')throw Error('请选择日期');const r=await api.historyExport({date});feedback('已导出 '+r.files+' 个文件：'+r.directory+(r.openError?'；文件夹未能打开：'+r.openError:''))});
 async function refresh(){if(refreshing)return;if(!api?.historyGet){feedback('请在 Windows 桌面应用中使用聊天记录功能');card.querySelectorAll('input,button,select').forEach(e=>e.disabled=true);return}refreshing=true;try{prefs=await api.historyGet();const select=q('#historyAccount'),old=select.value;select.replaceChildren();for(const a of [{id:'all-whatsapp',name:'全部 WhatsApp 账号'},...getAccounts()]){const o=document.createElement('option');o.value=a.id;o.textContent=a.name;select.append(o)}if([...select.options].some(o=>o.value===old))select.value=old;paint()}catch(e){feedback(e.message,true)}finally{refreshing=false}}
 refresh();return {element:card,refresh};
}
